import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.CdvW4CUT.js";const k=JSON.parse('{"title":"新增插件","description":"二次开发指南：新增部署插件、DNS 服务商、通知渠道与 CA，以及必须遵守的验收标准。","frontmatter":{"title":"新增插件","description":"二次开发指南：新增部署插件、DNS 服务商、通知渠道与 CA，以及必须遵守的验收标准。"},"headers":[],"relativePath":"docs/plugin-dev.md","filePath":"docs/plugin-dev.md","lastUpdated":null}'),i={name:"docs/plugin-dev.md"};function s(c,e,l,n,r,h){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="新增插件" tabindex="-1">新增插件 <a class="header-anchor" href="#新增插件" aria-label="Permalink to &quot;新增插件&quot;">​</a></h1><p>CertHub 是<strong>元数据驱动</strong>的：插件清单由后端注册表决定，前端表单、授权下拉、任务选择器全部自动生成。所以加功能不需要动前端。</p><h2 id="新增部署插件" tabindex="-1">新增部署插件 <a class="header-anchor" href="#新增部署插件" aria-label="Permalink to &quot;新增部署插件&quot;">​</a></h2><h3 id="第-1-步-写-handler" tabindex="-1">第 1 步：写 handler <a class="header-anchor" href="#第-1-步-写-handler" aria-label="Permalink to &quot;第 1 步：写 handler&quot;">​</a></h3><p>在 <code>backend/app/services/deploy.py</code>（或对应的 <code>deploy_*.py</code>）里实现：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> deploy_to_xxx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx: CertContext, config: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, log: Callable) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    log(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;开始部署 ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ctx.crt / ctx.key / ctx.pfx / ctx.domain / ctx.domains</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 路径里的变量用 ctx.render(&quot;...{{cert.domain}}...&quot;)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">两个约定</p><ol><li><strong><code>config</code> 里已经有授权内容</strong>。任务表单只存 <code>accessId</code>，引擎执行前会把授权里的地址、账号、密钥合并进 <code>config</code>（授权为底稿、任务入参覆盖），所以直接读 <code>config[&quot;url&quot;]</code> / <code>config[&quot;username&quot;]</code> 即可，不要再自己去查授权表。</li><li><strong>内网面板统一用 <code>_panel_request()</code> 发请求</strong>。它会关掉 <code>trust_env</code> —— 宿主机上若配了 <code>HTTP_PROXY</code>，httpx 默认会把 <code>192.168.x.x</code> 的内网请求也丢给代理，表现成「连不上」却看不出原因；同时把连接类异常翻成中文。公网云厂商接口不要用它，那些场景反而需要走代理。</li></ol></div><h3 id="第-2-步-注册-handler" tabindex="-1">第 2 步：注册 handler <a class="header-anchor" href="#第-2-步-注册-handler" aria-label="Permalink to &quot;第 2 步：注册 handler&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DEPLOY_HANDLERS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DeployToXxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deploy_to_xxx</span></span></code></pre></div><h3 id="第-3-步-登记元数据" tabindex="-1">第 3 步：登记元数据 <a class="header-anchor" href="#第-3-步-登记元数据" aria-label="Permalink to &quot;第 3 步：登记元数据&quot;">​</a></h3><p>在 <code>backend/app/plugins.py</code> 的 <code>TASK_PLUGINS</code> 里加一条（名称、描述、<code>inputs</code>、<code>category</code>、<code>logo</code>），前端会自动出现这个插件。</p><p><code>inputs</code> 里用 <code>f(&quot;key&quot;, &quot;标题&quot;, &quot;password&quot;)</code> 这样的工厂函数声明字段：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>component</code></td><td><code>input</code> / <code>password</code> / <code>select</code> / <code>switch</code> / <code>number</code> / <code>textarea</code> / <code>access</code> / <code>notification</code></td></tr><tr><td><code>options</code></td><td>select 的选项</td></tr><tr><td><code>showWhen</code></td><td>条件显示（例如只有开启两步验证才显示密钥字段）</td></tr><tr><td><code>accessTypes</code></td><td>授权字段只接受哪些精确类型</td></tr><tr><td><code>action</code></td><td>字段下方的动作按钮（例如群晖「获取设备 ID」）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">三个必须做的检查</p><ol><li><strong><code>accessId</code> 字段必须带 <code>accessTypes</code></strong>：只按 <code>accessCategory</code> 过滤会让「部署到群晖」的下拉里出现宝塔授权。注册表见 <code>_DEPLOY_ACCESS_TYPES</code>。</li><li><strong><code>inputs</code> 必须覆盖 handler 真正读的配置</strong>：把 handler 里所有 <code>config.get(&quot;xxx&quot;)</code> 的键抄出来对齐。群晖就踩过这个坑 —— handler 早就读 <code>asDefault</code>，但表单里没有这个开关，用户只能吃默认值。</li><li><strong>字段标题要写清楚去哪找</strong>，例如「两步验证密钥：DSM → 个人设置 → 双重验证」。</li></ol></div><h3 id="第-4-步-加-logo-可选" tabindex="-1">第 4 步：加 logo（可选） <a class="header-anchor" href="#第-4-步-加-logo-可选" aria-label="Permalink to &quot;第 4 步：加 logo（可选）&quot;">​</a></h3><p>厂商图标要<strong>本地化</strong>，不要让前端直连 CDN（内网、离线环境下会变成空白块）。图标文件放在 <code>frontend/public/logos/</code>，元数据里给相对路径 <code>logoFile</code>。</p><h2 id="新增-dns-服务商" tabindex="-1">新增 DNS 服务商 <a class="header-anchor" href="#新增-dns-服务商" aria-label="Permalink to &quot;新增 DNS 服务商&quot;">​</a></h2><ol><li>继承 <code>BaseDnsProvider</code>，实现 <code>add_txt</code> / <code>remove_txt</code>。</li><li>注册到 <code>dns.PROVIDERS</code>。</li><li><code>plugins.py</code> 的 <code>ACCESS_TYPES</code> 增加授权类型，<code>DNS_PROVIDERS</code> 增加条目。</li><li>如果该服务商能做 DNS-01 验证，把它的 key 加进 <code>_DNS_CAPABLE</code>，否则证书任务的「DNS 授权」下拉里不会出现它。</li></ol><h2 id="新增通知渠道" tabindex="-1">新增通知渠道 <a class="header-anchor" href="#新增通知渠道" aria-label="Permalink to &quot;新增通知渠道&quot;">​</a></h2><ol><li><code>notify.py</code> 实现 <code>send_xxx(config, title, content)</code>。</li><li>注册到 <code>SENDERS</code>。</li><li><code>plugins.py</code> 的 <code>NOTIFY_TYPES</code> 增加配置项。</li><li><strong>必须做业务码校验</strong>：很多国内渠道 token 错了也返回 HTTP 200，只在响应体里给 <code>errcode</code> / <code>code</code>。只判状态码会把「没发出去」记成成功。错误信息里只保留主机名，别把带 token 的完整 URL 写进日志。</li></ol><h2 id="新增-ca" tabindex="-1">新增 CA <a class="header-anchor" href="#新增-ca" aria-label="Permalink to &quot;新增 CA&quot;">​</a></h2><p>CA 的名称、目录地址、是否要 EAB <strong>只有 <code>plugins.ACME_PROVIDERS</code> 一份</strong>。引擎统一走 <code>_ca_name()</code> / <code>_ca_directory()</code> / <code>_ca_needs_eab()</code>，不要在引擎里手抄字典 —— 以前抄过，新增 FreeSSL 时漏改，表现是「选了 FreeSSL 却报『自定义 ACME 需要填写 ACME 目录地址』」。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><p>改完必须过这几关，缺一条都可能上线后翻车：</p><ol><li><code>python tests/smoke.py</code> 全绿（含插件一致性断言）。</li><li>前端能选到这个插件，表单字段齐全、必填项有校验。</li><li>授权类型不匹配时给出中文结论，而不是让用户对着数字 ID 猜。</li><li>错误路径有中文文案：业务异常只打一行，不甩堆栈，云厂商错误压成 <code>[Code] Message</code>。</li><li>新异常类登记到 <code>engine._EXPECTED_NAMES</code>，否则日志里会出现堆栈。</li><li>涉及凭据的字段，保存前 trim，留空不覆盖旧值。</li></ol><h2 id="相关约定" tabindex="-1">相关约定 <a class="header-anchor" href="#相关约定" aria-label="Permalink to &quot;相关约定&quot;">​</a></h2><p>项目根目录的 <code>AGENTS.md</code> 是硬性约定（凭据明文查看、元数据驱动、插件覆盖率、错误文案规范等），改代码前先读一遍。<strong>与代码冲突时以它为准，并回头把代码改对。</strong></p>`,27)])])}const g=o(i,[["render",s]]);export{k as __pageData,g as default};
